using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;
static class LocalHudFixture {
 static Memory m;static long b;static int checks;
 static void I(long off,int value){m.Write(b+off,BitConverter.GetBytes(value));}
 static void Check(bool value,string text){checks++;if(!value)throw new Exception(text);}
 static void Main(string[] args){var handle=Native.GetCurrentProcess();IntPtr block=IntPtr.Zero;for(long at=0x10000000;at<0x70000000&&block==IntPtr.Zero;at+=0x1000000)block=Native.VirtualAllocEx(handle,new IntPtr(at),new IntPtr(0x50000),0x3000,4);if(block==IntPtr.Zero)throw new Exception("No fixture memory");b=block.ToInt64();m=new Memory(handle);
 var p=new Profile {image_base=b,allocation=b+0x20000,symbols=new Dictionary<string,int>{{"gBattleWork",0},{"gBtlChars",0x2f00},{"gBtlSeq",0x2f04},{"gHud",0x2f08},{"online_mode",0x2f0c},{"gBtlObjTbl",0x11000}}};I(0x19f8,1);I(0x2f00,(int)(b+0x4000));I(0x2f04,(int)(b+0x4000));I(0x2f08,(int)(b+0x3000));I(0x3030,1);
 for(int side=0;side<2;side++){long actor=0x4000+side*0x2000,obj=0x9000+side*0x1000;I(actor,side);I(actor+12,side);I(actor+0x998,1);I(actor+0x9e4,12345);I(actor+0x9e8,30000);I(0x11000+side*4,(int)(b+obj));I(obj+0x92c,(int)(b+0xb000));I(obj+0x930,(int)(b+0xb400));I(obj+0xbc,(int)(b+0xc000+side*0x1000));m.Write(b+0xc000+side*0x1000,Encoding.Unicode.GetBytes(string.Join("\n",Enumerable.Range(0,5).Select(index=>"00*000"+(side==0?"Host":"Guest")+index))+"\0"));long mail=0x2f000+side*16;I(mail,2);I(mail+4,(int)(b+actor));I(mail+8,0x200);long card=0x2f100+side*128;I(card,2);I(card+4,(int)(b+actor));I(card+12,2);I(card+16,side);I(card+32,32);I(card+40,1);I(card+44,1);}
 for(int local=0;local<2;local++){I(0x2f0c,1);I(0x2f40c,local);var reader=new Reader(m,p);var moves=reader.Sample();Check(moves[0]!=null&&moves[1]==null,"Online moves not on local left side");Check(moves[0][0].Name==(local==0?"Host0":"Guest0"),"Wrong online actor selected");var cards=reader.SampleTransformations();Check(cards.Length==1&&cards[0].Side==local&&cards[0].DisplaySide==0,"Online cards not local left");Check(cards[0].Options[0].Health==12345,"Wrong roster gauge");}
 I(0x2f0c,0);var offline=new Reader(m,p);var both=offline.Sample();Check(both[0]!=null&&both[1]!=null,"Offline two-player move sides changed");var panels=offline.SampleTransformations();Check(panels.Length==2&&panels.Any(x=>x.DisplaySide==0)&&panels.Any(x=>x.DisplaySide==1),"Offline card sides changed");Console.WriteLine("PASS: "+checks+" local-HUD checks: host/guest display left, correct actor/roster, offline sides preserved.");
 }
}
